// Vite copies every imported original image into dist/_assets even when the
// page only references the resized renditions generated by astro:assets.
// Delete .webp files in dist/_assets that no built HTML/CSS/JS mentions.
// Runs from the postbuild hook, after terser.
import { readdirSync, readFileSync, statSync, unlinkSync } from 'node:fs';
import { join, extname } from 'node:path';

const DIST = new URL('../dist/', import.meta.url).pathname;
const ASSETS = join(DIST, '_assets');

const walk = (dir) =>
  readdirSync(dir).flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });

const referenced = walk(DIST)
  .filter((p) => ['.html', '.css', '.js', '.mjs', '.xml', '.webmanifest', '.json'].includes(extname(p)))
  .map((p) => readFileSync(p, 'utf8'))
  .join('\n');

let removed = 0;
let bytes = 0;
for (const file of walk(ASSETS).filter((p) => p.endsWith('.webp'))) {
  const basename = file.slice(file.lastIndexOf('/') + 1);
  if (!referenced.includes(basename)) {
    bytes += statSync(file).size;
    unlinkSync(file);
    removed++;
  }
}
console.log(`prune-unused-images: removed ${removed} unreferenced image(s), ${(bytes / 1024).toFixed(0)} kB`);
